CREATE OR REPLACE APPLICATION ROLE app_role;
CREATE OR REPLACE APPLICATION ROLE IF NOT EXISTS app_role COMMENT = 'app role comment';
CREATE OR ALTER APPLICATION ROLE app_role COMMENT = 'app role comment';
DEFINE APPLICATION ROLE app_role;
DEFINE APPLICATION ROLE app_role COMMENT = 'app role comment';

