ALTER APPLICATION ROLE "test_app_role" RENAME TO "prod_app_role";
ALTER APPLICATION ROLE app.role_name RENAME TO app.new_role_name;
ALTER APPLICATION ROLE IF EXISTS "test_app_role" SET COMMENT = 'test_comment';
