ALTER APPLICATION ROLE "test_app_role" SET COMMENT = 'test_comment';
ALTER APPLICATION ROLE "test_app_role" UNSET COMMENT;

DROP APPLICATION ROLE app_role;
DROP APPLICATION ROLE IF EXISTS app_role;
DROP APPLICATION ROLE "test_app_role";
DROP APPLICATION ROLE IF EXISTS "test_app_role";
